import { createOptimizedPicture } from '../../scripts/aem.js';

/**
 * cards-department: dense grid of department tiles with a "Show More" expander.
 * Content contract: one row per department.
 *   cell 1 = tile image (the source artwork already contains icon, label and tile border)
 *   cell 2 = department link (label as link text)
 * The tile image links to the department; the label link stays available to assistive tech
 * and is shown as a text tile when no image is authored.
 * On small screens the grid is collapsed (see CSS); a "Show More" / "Show Less" toggle is
 * generated by the block, never authored.
 */
let instanceCount = 0;

export default function decorate(block) {
  instanceCount += 1;
  const ul = document.createElement('ul');
  ul.className = 'cards-department-list';
  ul.id = `cards-department-${instanceCount}-list`;

  [...block.children].forEach((row) => {
    const cells = [...row.children];
    if (!cells.some((c) => c.textContent.trim() || c.querySelector('picture, img'))) return;

    const li = document.createElement('li');
    li.className = 'cards-department-card';
    const imageCell = cells.find((c) => c.querySelector('picture, img'));
    const body = document.createElement('div');
    body.className = 'cards-department-card-body';
    cells.filter((c) => c !== imageCell).forEach((c) => body.append(...c.childNodes));

    const link = body.querySelector('a[href]') || imageCell?.querySelector('a[href]');
    if (imageCell) {
      imageCell.className = 'cards-department-card-image';
      li.classList.add('has-image');
      const pic = imageCell.querySelector('picture, img');
      const imgLink = imageCell.querySelector('a[href]');
      if (link && !imgLink) {
        // decorative duplicate of the label link, so the whole artwork is clickable
        const a = document.createElement('a');
        a.href = link.href;
        a.tabIndex = -1;
        a.setAttribute('aria-hidden', 'true');
        pic.replaceWith(a);
        a.append(pic);
      } else if (imgLink && imgLink !== link) {
        imgLink.tabIndex = -1;
        imgLink.setAttribute('aria-hidden', 'true');
      }
      li.append(imageCell);
    }
    if (link) link.classList.add('cards-department-card-link');
    if (body.textContent.trim()) li.append(body);
    ul.append(li);
  });

  ul.querySelectorAll('picture > img').forEach((img) => {
    img.closest('picture').replaceWith(createOptimizedPicture(img.src, img.alt, false, [{ width: '400' }]));
  });

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'cards-department-toggle';
  toggle.setAttribute('aria-controls', ul.id);
  toggle.setAttribute('aria-expanded', 'false');
  toggle.textContent = 'Show More';
  toggle.addEventListener('click', () => {
    const expanded = block.classList.toggle('is-expanded');
    toggle.setAttribute('aria-expanded', expanded);
    toggle.textContent = expanded ? 'Show Less' : 'Show More';
  });

  const actions = document.createElement('div');
  actions.className = 'cards-department-actions';
  actions.append(toggle);
  block.replaceChildren(ul, actions);
}
